registerTtsSttMusicV52Routes(app);
registerTtsSttMusicV53Routes(app);
registerTtsSttMusicV54Routes(app);
registerTtsSttMusicV55Routes(app);
registerTtsSttMusicV56Routes(app);
registerTtsSttMusicV57Routes(app);
registerTtsSttMusicV58Routes(app);
registerTtsSttMusicV59Routes(app);
registerTtsSttMusicV60Routes(app);
registerTtsSttMusicV61Routes(app);
registerTtsSttMusicV62Routes(app);
registerTtsSttMusicV63Routes(app);
registerTtsSttMusicV64Routes(app);
app.use("/trpc", createExpressMiddleware({ router: appRouter, createContext }));
const port = env.port;
app.listen(port, () => {
    console.log(`Pinuyumayan backend database API listening on :${port}`);
});
